sql.if:
AND EXISTS (
	SELECT 1
	FROM voj_problem_category_relationships pcr
	WHERE pcr.problem_id = p.problem_id
	AND pcr.problem_category_id = #{problemCategoryId}
)

AND EXISTS (
	SELECT 1
	FROM voj_problem_tag_relationships ptr
	WHERE ptr.problem_id = p.problem_id
	AND ptr.problem_tag_id = #{problemTagId}
)

mapper.select:
SELECT p.*, d.problem_difficulty_slug, d.problem_difficulty_name, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id
) AS total_submission, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id AND s.submission_judge_result = 'AC'
) AS accepted_submission FROM voj_problems p LEFT JOIN voj_problem_difficulty d ON d.problem_difficulty_id = p.problem_difficulty_id WHERE p.problem_id = #{problemId}

SELECT p.*, d.problem_difficulty_slug, d.problem_difficulty_name, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id
) AS total_submission, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id AND s.submission_judge_result = 'AC'
) AS accepted_submission FROM voj_contest_problems cp JOIN voj_problems p ON p.problem_id = cp.problem_id LEFT JOIN voj_problem_difficulty d ON d.problem_difficulty_id = p.problem_difficulty_id WHERE cp.contest_id = #{contestId} ORDER BY cp.position

SELECT p.problem_id, p.problem_name, p.problem_status, p.problem_difficulty_id, d.problem_difficulty_slug, d.problem_difficulty_name, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id
) AS total_submission, ( SELECT COUNT(*) FROM voj_submissions s WHERE s.problem_id = p.problem_id AND s.submission_judge_result = 'AC'
) AS accepted_submission FROM voj_problems p LEFT JOIN voj_problem_difficulty d ON d.problem_difficulty_id = p.problem_difficulty_id WHERE 1 = 1
ORDER BY p.problem_id LIMIT #{offset}, #{limit}

mapper.update:
UPDATE voj_problems 
SET problem_status = #{status}, problem_name = #{problemName}, problem_difficulty_id = #{problemDifficulty.problemDifficultyId}, problem_time_limit = #{timeLimit}, problem_memory_limit = #{memoryLimit}, problem_description = #{description}, problem_input_format = #{inputFormat}, problem_output_format = #{outputFormat}, problem_sample_input = #{sampleInput}, problem_sample_output = #{sampleOutput}, problem_hint = #{hint} 
WHERE problem_id = #{problemId}

mapper.select:
SELECT checkpoints_version
FROM voj_problems
WHERE problem_id = #{problemId}

mapper.update:
UPDATE voj_problems
SET checkpoints_version = checkpoints_version + 1
WHERE problem_id = #{problemId}
